package com.bank.core;

import java.util.concurrent.Executors;

// Java 21 Enterprise Feature Showcase: Record, Pattern Matching & Virtual Threads
public class JavaEcosystemDemo {

    public sealed interface PaymentStatus permits Success, Failed {}
    public record Success(String txId, long amountCents) implements PaymentStatus {}
    public record Failed(String reason, int errorCode) implements PaymentStatus {}

    public static String handlePayment(PaymentStatus status) {
        // Modern Pattern Matching for Switch (Java 21)
        return switch (status) {
            case Success s when s.amountCents() > 1_000_000_00L -> 
                "VIP Transaction Approved: " + s.txId();
            case Success s -> 
                "Standard Transaction Approved: " + s.txId();
            case Failed f -> 
                "Alert: Payment rejected due to " + f.reason();
        };
    }

    public static void main(String[] args) {
        // High-Throughput Lightweight Concurrency via Virtual Threads
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            for (int i = 0; i < 5; i++) {
                final int txIndex = i;
                executor.submit(() -> {
                    var status = (txIndex % 2 == 0) 
                        ? new Success("TX-" + txIndex, 5_000_000_00L) 
                        : new Failed("Insufficient Funds", 402);
                    System.out.println(Thread.currentThread() + " -> " + handlePayment(status));
                });
            }
        } // Auto-closes and drains all virtual tasks cleanly
    }
}

package com.bank.auth;

import java.util.Objects;

public final class AccountId {
    private final String prefix;
    private final long number;

    public AccountId(String prefix, long number) {
        this.prefix = Objects.requireNonNull(prefix, "prefix cannot be null");
        this.number = number;
    }

    @Override
    public boolean equals(Object o) {
        // 1. Tối ưu danh tính ô nhớ (Fast-path)
        if (this == o) return true;
        // 2. Kiểm tra type chính xác (hoặc instanceof nếu class không final)
        if (o == null || getClass() != o.getClass()) return false;
        // 3. Ép kiểu và so sánh từng trường dữ liệu logic
        AccountId that = (AccountId) o;
        return this.number == that.number && Objects.equals(this.prefix, that.prefix);
    }

    @Override
    public int hashCode() {
        return Objects.hash(prefix, number);
    }

    public static void main(String[] args) {
        AccountId id1 = new AccountId("VND", 1001L);
        AccountId id2 = new AccountId("VND", 1001L);

        System.out.println("Reference equality (==): " + (id1 == id2)); // false (2 ô nhớ Heap riêng)
        System.out.println("Value equality (.equals): " + id1.equals(id2)); // true (cùng logic nghiệp vụ)
    }
}

package com.bank.marketdata;

public class MemoryEfficiencyDemo {
    public static void main(String[] args) {
        int size = 5_000_000;

        // Primitive array: Flat continuous memory block in Heap (8 bytes * 5M = ~40MB)
        // Cache locality tuyệt đối, zero GC overhead cho từng phần tử
        long startMem = getUsedMemory();
        long startTime = System.nanoTime();

        double[] primitivePrices = new double[size];
        for (int i = 0; i < size; i++) {
            primitivePrices[i] = 100.5 + i;
        }

        long primitiveDuration = System.nanoTime() - startTime;
        long primitiveMemUsed = getUsedMemory() - startMem;

        System.out.printf("Primitive double[]: %d ms, ~%d MB allocated%n", 
            primitiveDuration / 1_000_000, primitiveMemUsed / (1024 * 1024));
    }

    private static long getUsedMemory() {
        Runtime rt = Runtime.getRuntime();
        return rt.totalMemory() - rt.freeMemory();
    }
}

package com.bank.memory;

public class StackVsHeapDemo {

    // Immutable Point: Ứng viên hoàn hảo cho Escape Analysis
    record GeoPoint(double lat, double lon) {}

    public double calculateDistance() {
        // point chỉ tồn tại trong phạm vi method này (No Escape!)
        // C2 Compiler sẽ loại bỏ 'new' trên Heap và map lat, lon trực tiếp vào CPU registers
        GeoPoint point = new GeoPoint(10.762622, 106.660172); 
        return point.lat() * 2 + point.lon();
    }

    public static void main(String[] args) {
        StackVsHeapDemo demo = new StackVsHeapDemo();

        // JVM Warm-up để kích hoạt JIT C2 Compiler (-XX:+DoEscapeAnalysis)
        double sum = 0;
        for (int i = 0; i < 100_000; i++) {
            sum += demo.calculateDistance();
        }
        System.out.println("Computed total: " + sum);
    }
}

package com.bank.observability;

import jdk.jfr.Event;
import jdk.jfr.Label;
import jdk.jfr.Name;

// Java Enterprise Characteristic: Production Observability via JDK Flight Recorder (JFR)
public class EnterpriseFeatureDemo {

    @Name("com.bank.TransactionEvent")
    @Label("Financial Transaction Processing")
    static class TransactionEvent extends Event {
        @Label("Account ID")
        String accountId;
        @Label("Amount Cents")
        long amount;
    }

    public static void executeTransaction(String accountId, long amount) {
        TransactionEvent event = new TransactionEvent();
        event.accountId = accountId;
        event.amount = amount;
        event.begin(); // Đánh dấu thời điểm bắt đầu đo đạc với overhead < 1% CPU

        try {
            // Logic giao dịch ngân hàng an toàn đa luồng
            Thread.sleep(2); 
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            event.commit(); // Ghi trực tiếp vào ring-buffer native memory của JFR
        }
    }

    public static void main(String[] args) {
        executeTransaction("ACC-88899", 250_000_00L);
        System.out.println("Transaction recorded with zero third-party agent overhead.");
    }
}

package com.bank.security;

import java.util.HashMap;
import java.util.Map;

public class StringImmutabilityDemo {
    public static void main(String[] args) {
        // 1. Thread Safety & Safe Sharing: Không lo bị mutate ngầm
        String baseKey = "USER_SESSION_";
        String fullKey = baseKey.concat("9981"); // Tạo ra String mới, baseKey giữ nguyên

        // 2. HashCode Caching: Tối ưu tra cứu Map
        Map<String, String> tokenCache = new HashMap<>();
        tokenCache.put(fullKey, "SESSION_DATA_TOKEN");

        // HashCode của fullKey được tính 1 lần duy nhất và tái sử dụng mãi mãi
        String result = tokenCache.get(fullKey);
        System.out.println("Lookup result: " + result);

        // 3. Immutability ngăn chặn TOCTOU Attack
        validateAndExecute(fullKey);
    }

    private static void validateAndExecute(String sessionToken) {
        // Nếu String là mutable, một luồng khác có thể can thiệp sửa đổi sessionToken
        // tại đây trước khi lệnh bên dưới thực thi (TOCTOU Vulnerability)!
        if (sessionToken.startsWith("USER_SESSION_")) {
            System.out.println("Authorized execution for: " + sessionToken);
        }
    }
}

package com.bank.domain;

import java.math.BigDecimal;
import java.util.Objects;

public final class PaymentOrder {
    private final String orderId;
    private final BigDecimal amount;
    private final String currency;
    private final String description;

    // 1. Canonical Constructor: Nơi duy nhất thực hiện Validation Invariants
    public PaymentOrder(String orderId, BigDecimal amount, String currency, String description) {
        this.orderId = Objects.requireNonNull(orderId, "orderId required");
        if (amount == null || amount.compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Amount must be strictly positive");
        }
        this.amount = amount;
        this.currency = Objects.requireNonNull(currency, "currency required");
        this.description = (description != null) ? description : "";
    }

    // 2. Overloaded Constructor (2 tham số): Gán giá trị mặc định và ủy quyền qua this(...)
    public PaymentOrder(String orderId, BigDecimal amount) {
        this(orderId, amount, "VND", "Standard Transfer");
    }

    // 3. Overloaded Constructor (3 tham số)
    public PaymentOrder(String orderId, BigDecimal amount, String currency) {
        this(orderId, amount, currency, "Standard Transfer");
    }

    public static void main(String[] args) {
        PaymentOrder order1 = new PaymentOrder("ORD-001", new BigDecimal("150000"));
        PaymentOrder order2 = new PaymentOrder("ORD-002", new BigDecimal("500"), "USD", "Server Subscription");
        System.out.println("Orders initialized safely with invariant checks.");
    }
}

package com.bank.crypto;

// Public interface: Phơi bày ra ngoài API SDK
public interface PaymentSigner {
    byte[] signPayload(byte[] payload);
}

// Package-private class: Giấu kín thuật toán, không cho package bên ngoài sờ tới
class HmacSha256Signer implements PaymentSigner {
    private final byte[] secretKey;

    // Package-private constructor
    HmacSha256Signer(byte[] secretKey) {
        this.secretKey = secretKey.clone();
    }

    @Override
    public byte[] signPayload(byte[] payload) {
        return internalDigest(payload); // Private method
    }

    private byte[] internalDigest(byte[] data) {
        // Thuật toán băm mật mã bảo mật
        return new byte[]{0x01, 0x02, (byte) data.length};
    }
}

// Public Factory: Điểm truy cập duy nhất có kiểm soát
public class SignerFactory {
    public static PaymentSigner createDefault(byte[] secret) {
        return new HmacSha256Signer(secret);
    }
}

package com.bank.pricing;

class Customer {
    public double getDiscountRate() {
        return 0.0; // 0%
    }
}

class VipCustomer extends Customer {
    @Override
    public double getDiscountRate() {
        return 0.15; // 15% discount (Dynamic Runtime Overriding)
    }
}

public class PricingEngine {
    // Method Overloading 1: Kiểu Customer cơ bản
    public double calculateTotal(Customer c, double amount) {
        System.out.println("Dispatched via compile-time signature: calculateTotal(Customer)");
        return amount * (1.0 - c.getDiscountRate()); // Late binding call tới getDiscountRate()
    }

    // Method Overloading 2: Chữ ký tham số thêm coupon
    public double calculateTotal(Customer c, double amount, double couponVoucher) {
        return calculateTotal(c, amount) - couponVoucher;
    }

    public static void main(String[] args) {
        PricingEngine engine = new PricingEngine();
        Customer vip = new VipCustomer(); // Polymorphic reference

        // Early binding chọn method calculateTotal(Customer, double)
        // Late binding bên trong sẽ kích hoạt getDiscountRate() của VipCustomer
        double total = engine.calculateTotal(vip, 1_000_000);
        System.out.println("Final total: " + total); // Giảm 15% còn 850,000
    }
}

package com.bank.domain.core;

import java.math.BigDecimal;

// 2. Abstraction: Contract chuyển tiền
interface TransferService {
    void transfer(BankAccount from, BankAccount to, BigDecimal amount);
}

// 1. Encapsulation: Bảo vệ số dư không cho can thiệp trực tiếp từ bên ngoài
class BankAccount {
    private final String accountNumber;
    private BigDecimal balance; // Private state

    public BankAccount(String accountNumber, BigDecimal initialBalance) {
        this.accountNumber = accountNumber;
        this.balance = initialBalance;
    }

    public synchronized void debit(BigDecimal amount) {
        if (amount.compareTo(BigDecimal.ZERO) <= 0 || balance.compareTo(amount) < 0) {
            throw new IllegalStateException("Insufficient balance or invalid amount");
        }
        this.balance = this.balance.subtract(amount); // State mutation có kiểm soát
    }

    public synchronized void credit(BigDecimal amount) {
        this.balance = this.balance.add(amount);
    }

    public BigDecimal getBalance() { return balance; }
}

// 3. Inheritance & 4. Polymorphism: Triển khai linh hoạt từng kênh thanh toán
abstract class AbstractTransferService implements TransferService {
    // Tái sử dụng logic kiểm toán chung
    protected void audit(String log) { System.out.println("[AUDIT] " + log); }
}

class NapasTransferService extends AbstractTransferService {
    @Override
    public void transfer(BankAccount from, BankAccount to, BigDecimal amount) {
        from.debit(amount);
        to.credit(amount);
        audit("NAPAS 247 Instant Transfer executed successfully");
    }
}

package com.bank.fx;

import java.math.BigDecimal;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public final class ExchangeRateProvider {

    // 1. Static Final Constant: Bất biến, tối ưu bộ nhớ
    public static final String BASE_CURRENCY = "USD";

    // 2. Thread-safe Static State: Dùng cấu trúc concurrent chuyên dụng
    private static final Map<String, BigDecimal> RATES = new ConcurrentHashMap<>();

    // Private constructor ngăn chặn khởi tạo instance vô nghĩa
    private ExchangeRateProvider() {}

    // 3. Static Utility Method: Không trạng thái, xử lý nhanh
    public static BigDecimal convert(String targetCurrency, BigDecimal amount) {
        BigDecimal rate = RATES.getOrDefault(targetCurrency, BigDecimal.ONE);
        return amount.multiply(rate);
    }

    // 4. Bill Pugh Thread-Safe Lazy Initialization Idiom
    private static class SingletonHolder {
        private static final ExchangeRateProvider INSTANCE = new ExchangeRateProvider();
    }

    public static ExchangeRateProvider getInstance() {
        return SingletonHolder.INSTANCE; // ClassLoader đảm bảo an toàn tuyệt đối
    }
}

package com.bank.payment;

import java.util.Objects;
import java.util.Optional;

public class ZeroNpeArchitecture {

    record CustomerProfile(String customerId, Address address) {}
    record Address(String city, String zipCode) {}

    // 1. Fail-fast validation ngay tại ranh giới đầu vào
    public void registerCustomer(CustomerProfile profile) {
        Objects.requireNonNull(profile, "Profile must not be null");
        Objects.requireNonNull(profile.customerId(), "Customer ID is mandatory");
    }

    // 2. Trả về Optional thay vì trả về null
    public Optional<Address> findAddress(CustomerProfile profile) {
        return Optional.ofNullable(profile.address());
    }

    // 3. Java 21 Pattern Matching hỗ trợ null-case an toàn tuyệt đối
    public static String resolveRouting(Object request) {
        return switch (request) {
            case null -> "Default Fallback Route (Null-safe)";
            case CustomerProfile c when c.address() == null -> "Direct Registration (No Address)";
            case CustomerProfile c -> "Full Registration for: " + c.customerId();
            default -> "Unknown Request Type";
        };
    }

    public static void main(String[] args) {
        CustomerProfile guest = new CustomerProfile("CUST-01", null);
        System.out.println(resolveRouting(guest));
        System.out.println(resolveRouting(null)); // Không bao giờ văng NPE
    }
}

package com.bank.exceptions;

public class BankingExceptionArchitecture {

    // Base Domain Exception
    public static class BasePaymentException extends RuntimeException {
        private final String errorCode;

        public BasePaymentException(String errorCode, String message, Throwable cause) {
            super(message, cause); // Gọi constructor của RuntimeException bằng super
            this.errorCode = errorCode; // this phân biệt field với tham số
        }

        public String getDetailedLog() {
            return "[ErrorCode: " + errorCode + "] " + getMessage();
        }
    }

    // Subclass: Kế thừa và mở rộng
    public static class InsufficientBalanceException extends BasePaymentException {
        private final long requiredCents;

        public InsufficientBalanceException(long requiredCents) {
            // Constructor Chaining trong cùng class bằng this(...)
            this("ERR_PAY_001", "Balance too low for operation", requiredCents);
        }

        public InsufficientBalanceException(String code, String msg, long requiredCents) {
            super(code, msg, null); // Ủy quyền khởi tạo lên lớp cha bằng super
            this.requiredCents = requiredCents;
        }

        @Override
        public String getDetailedLog() {
            // Gọi lại method của lớp cha qua super và bổ sung ngữ cảnh mới
            return super.getDetailedLog() + " | Required Cents: " + this.requiredCents;
        }
    }

    public static void main(String[] args) {
        var ex = new InsufficientBalanceException(500_000_00L);
        System.out.println(ex.getDetailedLog());
    }
}

package com.bank.event;

import java.util.List;

// 3. Final Class: Không thể bị kế thừa, chống subclass phá hoại kiến trúc
public final class TradeExecutedEvent {

    // 1. Final Fields: JMM Freeze Action đảm bảo Safe Publication đa luồng
    private final String tradeId;
    private final long executionTimestamp;
    private final List<String> symbols;

    public TradeExecutedEvent(String tradeId, List<String> symbols) {
        this.tradeId = tradeId;
        this.executionTimestamp = System.currentTimeMillis();
        // Defensive copy để bảo vệ tính bất biến thực sự của List nội bộ
        this.symbols = List.copyOf(symbols);
    }

    // 2. Final Method: Đảm bảo thuật toán hashing an toàn không bị sửa đổi
    public final String generateAuditKey() {
        return tradeId + ":" + executionTimestamp;
    }

    public String getTradeId() { return tradeId; }
    public List<String> getSymbols() { return symbols; }

    public static void main(String[] args) {
        var event = new TradeExecutedEvent("TR-998", List.of("AAPL", "MSFT"));
        System.out.println("Safe published event: " + event.generateAuditKey());
    }
}

package com.bank.gateway;

// 1. Interface: Contract hành vi thuần túy (Can-do)
public interface Auditable {
    void logAudit(String event);
}

// 2. Sealed Interface hiện đại (Java 17)
public sealed interface PaymentGateway permits AbstractCardGateway, EWalletGateway {
    boolean processPayment(String txId, long amountCents);

    // Default method cung cấp hành vi mở rộng mà không làm gãy implementations cũ
    default String getGatewayVersion() {
        return "v2.1-enterprise";
    }
}

// 3. Abstract Class: Giữ state kết nối và áp dụng Template Method Pattern (Is-a)
public abstract non-sealed class AbstractCardGateway implements PaymentGateway, Auditable {
    protected final String merchantId; // Instance state được bảo vệ

    protected AbstractCardGateway(String merchantId) {
        this.merchantId = merchantId;
    }

    // Template Method định hình quy trình thanh toán bất biến
    @Override
    public final boolean processPayment(String txId, long amountCents) {
        logAudit("Starting transaction: " + txId);
        boolean result = executeCharge(txId, amountCents); // Lớp con cụ thể triển khai
        logAudit("Finished transaction with status: " + result);
        return result;
    }

    protected abstract boolean executeCharge(String txId, long amountCents);
}

final class EWalletGateway implements PaymentGateway {
    @Override
    public boolean processPayment(String txId, long amountCents) {
        return true;
    }
}

package com.bank.repository;

public class TextBlockEnterpriseDemo {

    public static String buildPaymentQuery(String schema, String status, int limit) {
        // Text block SQL sạch sẽ, trực quan, không cần escape \" hay nối dòng \n
        String sqlTemplate = """
            SELECT 
                t.transaction_id,
                t.amount_cents,
                t.currency,
                t.created_at
            FROM %s.transactions t
            WHERE t.status = '%s'
              AND t.created_at >= NOW() - INTERVAL '24 HOURS'
            ORDER BY t.created_at DESC
            LIMIT %d;
            """;

        return sqlTemplate.formatted(schema, status, limit); // Tiện ích formatted tích hợp sẵn
    }

    public static String buildJsonPayload(String txId, long amount) {
        // Text block JSON: Dấu ngoặc kép được giữ nguyên tự nhiên
        return """
            {
                "transactionId": "%s",
                "amountCents": %d,
                "status": "PENDING"
            }
            """.formatted(txId, amount);
    }

    public static void main(String[] args) {
        System.out.println(buildPaymentQuery("core_bank", "COMPLETED", 10));
        System.out.println(buildJsonPayload("TX-0098", 150_000_00L));
    }
}

package com.bank.io;

import java.io.Closeable;

public class ResourceCleanupDemo {

    // 1. final modifier: Immutable configuration
    private final String connectionUrl;

    public ResourceCleanupDemo(String connectionUrl) {
        this.connectionUrl = connectionUrl;
    }

    static class MockDatabaseConnection implements Closeable {
        public void query() { System.out.println("Executing database query..."); }
        @Override
        public void close() { System.out.println("Connection closed safely via AutoCloseable."); }
    }

    public void executeQuery() {
        // Modern standard: try-with-resources thay thế hoàn toàn finally truyền thống
        try (MockDatabaseConnection conn = new MockDatabaseConnection()) {
            conn.query();
        } catch (Exception e) {
            System.err.println("Error executing query: " + e.getMessage());
        } finally {
            // 2. finally block: Luôn chạy để giải phóng tài nguyên không thuộc AutoCloseable
            System.out.println("Finally block executed unconditionally.");
        }
    }

    // 3. finalize() tuyệt đối KHÔNG ĐƯỢC DÙNG (Deprecated for Removal)
    // Thay vào đó dùng Cleaner API nếu thực sự cần dọn dẹp off-heap native memory

    public static void main(String[] args) {
        var demo = new ResourceCleanupDemo("jdbc:postgresql://db:5432/core");
        demo.executeQuery();
    }
}

package com.bank.stringpool;

public class StringPoolArchitecture {
    public static void main(String[] args) {
        // 1. String Literal: Lưu trữ và tái sử dụng từ String Pool
        String s1 = "VCB";
        String s2 = "VCB"; // Trỏ cùng địa chỉ ô nhớ trong String Pool

        // 2. new String(): Ép cấp phát object mới hoàn toàn trên Java Heap
        String s3 = new String("VCB");

        // 3. String.intern(): Đưa tham chiếu vào String Pool hoặc lấy ra tham chiếu đã có
        String s4 = s3.intern();

        System.out.println("s1 == s2 (Cùng Pool reference): " + (s1 == s2)); // true
        System.out.println("s1 == s3 (Heap instance vs Pool): " + (s1 == s3)); // false
        System.out.println("s1 == s4 (Sau khi intern s3): " + (s1 == s4));     // true
        System.out.println("s1.equals(s3) (Nội dung logic): " + s1.equals(s3)); // true
    }
}

package com.bank.cache;

public class IntegerCacheDemo {
    public static void main(String[] args) {
        // Autoboxing tự động dịch thành Integer.valueOf(...)
        Integer a = 127;
        Integer b = 127;
        System.out.println("127 == 127: " + (a == b)); // true (Cùng trỏ tới IntegerCache)

        Integer c = 128;
        Integer d = 128;
        System.out.println("128 == 128 (Identity): " + (c == d)); // false (2 Object riêng trên Heap)
        System.out.println("128.equals(128) (Value): " + c.equals(d)); // true (So sánh giá trị)

        // Cách viết chuẩn chỉnh trong hệ thống ngân hàng:
        boolean isSame = java.util.Objects.equals(c, d);
        System.out.println("Null-safe value comparison: " + isSame); // true
    }
}

package com.bank.cleanup;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

public class SafeCollectionRemovalDemo {

    record UserSession(String sessionId, boolean isExpired) {}

    public static void main(String[] args) {
        List<UserSession> sessions = new ArrayList<>();
        sessions.add(new UserSession("S1", false));
        sessions.add(new UserSession("S2", true));
        sessions.add(new UserSession("S3", true));
        sessions.add(new UserSession("S4", false));

        // CÁCH 1 (Cổ điển): Dùng Iterator.remove()
        Iterator<UserSession> it = sessions.iterator();
        while (it.hasNext()) {
            UserSession session = it.next();
            if (session.sessionId().equals("S2")) {
                it.remove(); // Hợp lệ và an toàn!
            }
        }

        // CÁCH 2 (Hiện đại & Tối ưu O(N)): Dùng Collection.removeIf (Java 8+)
        // Xóa sạch các session hết hạn chỉ trong một lần dịch mảng
        sessions.removeIf(UserSession::isExpired);

        System.out.println("Remaining active sessions: " + sessions.size()); // Còn lại S1, S4
    }
}

package com.bank.collections;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class ArraysAsListDemo {
    public static void main(String[] args) {
        String[] rawRoles = {"AUDITOR", "OPERATOR"};

        // 1. Arrays.asList: Fixed-size view trên mảng rawRoles
        List<String> fixedList = Arrays.asList(rawRoles);
        fixedList.set(0, "SENIOR_AUDITOR"); // Thành công! Cập nhật mảng gốc rawRoles[0]
        System.out.println("Raw array mutated: " + rawRoles[0]); // SENIOR_AUDITOR

        try {
            fixedList.add("SUPER_ADMIN"); // Ném UnsupportedOperationException!
        } catch (UnsupportedOperationException e) {
            System.out.println("Cannot add to fixed-size Arrays$ArrayList!");
        }

        // 2. Cách tạo Resizable List chuẩn mực:
        List<String> mutableList = new ArrayList<>(Arrays.asList(rawRoles));
        mutableList.add("SUPER_ADMIN"); // Thành công 100%

        // 3. Cách tạo Immutable List chuẩn Java 9+:
        List<String> immutableList = List.of("READ_ONLY", "FINANCE");
        System.out.println("List.of size: " + immutableList.size());
    }
}

