package com.bank.concurrency;

import java.util.concurrent.locks.LockSupport;

public class ThreadLifecycleDemo {
    public static void main(String[] args) throws InterruptedException {
        Object lock = new Object();

        // 1. Trạng thái NEW
        Thread worker = new Thread(() -> {
            synchronized (lock) {
                try {
                    // 4. Trạng thái TIMED_WAITING
                    Thread.sleep(100);
                    // 5. Trạng thái WAITING (nhường lock)
                    lock.wait();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });
        System.out.println("State 1: " + worker.getState()); // NEW

        // 2. Chuyển sang RUNNABLE
        worker.start();
        System.out.println("State 2: " + worker.getState()); // RUNNABLE

        Thread.sleep(20); // Chờ worker vào sleep
        System.out.println("State 3: " + worker.getState()); // TIMED_WAITING

        Thread.sleep(150); // Chờ worker gọi wait()
        System.out.println("State 4: " + worker.getState()); // WAITING

        // Đánh thức worker để kết thúc
        synchronized (lock) { lock.notify(); }
        worker.join();
        System.out.println("State 5: " + worker.getState()); // TERMINATED
    }
}

package com.bank.async;

import java.util.concurrent.*;

public class RunnableVsCallableDemo {

    public static void main(String[] args) throws Exception {
        try (ExecutorService pool = Executors.newFixedThreadPool(2)) {

            // 1. Runnable: Fire-and-forget, void return, không ném checked exception
            Runnable auditTask = () -> {
                System.out.println("Audit log recorded on: " + Thread.currentThread().getName());
            };
            pool.execute(auditTask);

            // 2. Callable: Trả về kết quả kiểu V, hỗ trợ ném Checked Exception
            Callable<Long> balanceCalculator = () -> {
                // Giả lập tính toán phức tạp hoặc gọi network
                if (System.currentTimeMillis() % 2 == 0) {
                    return 250_000_000L; // Trả về số dư
                } else {
                    throw new IllegalStateException("External Ledger Timeout");
                }
            };

            Future<Long> future = pool.submit(balanceCalculator);

            try {
                Long balance = future.get(1, TimeUnit.SECONDS); // Blocking chờ kết quả có timeout
                System.out.println("Calculated balance: " + balance);
            } catch (ExecutionException e) {
                // Checked exception trong Callable được bọc an toàn trong ExecutionException
                System.err.println("Underlying exception: " + e.getCause().getMessage());
            }
        }
    }
}

package com.bank.threads;

public class DaemonThreadLifecycleDemo {
    public static void main(String[] args) {
        // 1. Tạo một Daemon Thread (ví dụ: Metric Heartbeat Collector)
        Thread metricCollector = new Thread(() -> {
            try {
                while (true) {
                    System.out.println("[Daemon] Sending heartbeat ping to monitoring server...");
                    Thread.sleep(500);
                }
            } catch (InterruptedException e) {
                System.out.println("[Daemon] Interrupted cleanly");
            } finally {
                // CẢNH BÁO: Khi main thread kết thúc, dòng này nhiều khả năng KHÔNG KỊP CHẠY!
                System.out.println("[Daemon] Finally block cleaned up resources!");
            }
        });

        // Bắt buộc cấu hình trước khi start()
        metricCollector.setDaemon(true);
        metricCollector.start();

        // 2. Main Thread (User Thread) chạy ngắn hạn
        System.out.println("[Main] User Thread processing quick transaction...");
        try {
            Thread.sleep(1200); // Cho daemon in 2 lần
        } catch (InterruptedException ignored) {}

        System.out.println("[Main] User Thread finishes. JVM will exit immediately!");
        // Tại thời điểm này JVM thoát, metricCollector bị tiêu diệt ngay lập tức
    }
}

