        long startBuffer = System.nanoTime();
        StringBuffer sbf = new StringBuffer(iterations * 12);
        for (int i = 0; i < iterations; i++) {
            sbf.append("TX-").append(i).append(';');
        }
        long durationBuffer = (System.nanoTime() - startBuffer) / 1_000_000;
        System.out.printf("StringBuffer duration: %d ms (overhead due to sync)%n", durationBuffer);
