package com.bank.benchmark;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

public class ListHardwareEfficiencyBenchmark {
    public static void main(String[] args) {
        int elementCount = 500_000;

        // 1. Benchmark ArrayList Iteration (CPU Cache Friendly)
        List<Integer> arrayList = new ArrayList<>(elementCount);
        for (int i = 0; i < elementCount; i++) arrayList.add(i);

        long startArray = System.nanoTime();
        long sumArray = 0;
        for (int i = 0; i < elementCount; i++) {
            sumArray += arrayList.get(i); // Trực tiếp tính offset ô nhớ: base + i * 4
        }
        long durationArray = System.nanoTime() - startArray;

        // 2. Benchmark LinkedList Iteration via get(i) (Thảm họa O(N^2) và Cache Miss)
        List<Integer> linkedList = new LinkedList<>();
        for (int i = 0; i < 20_000; i++) linkedList.add(i); // Giảm size vì O(N^2) quá chậm

        long startLinked = System.nanoTime();
        long sumLinked = 0;
        for (int i = 0; i < linkedList.size(); i++) {
            sumLinked += linkedList.get(i); // Phải duyệt con trỏ từ đầu/cuối đến index!
        }
        long durationLinked = System.nanoTime() - startLinked;

        System.out.printf("ArrayList (500k items) random access: %d ms%n", durationArray / 1_000_000);
        System.out.printf("LinkedList (chỉ 20k items) get(i) traversal: %d ms%n", durationLinked / 1_000_000);
    }
}

