package com.bank.iterator;

import java.util.Iterator;
import java.util.NoSuchElementException;

// Custom Collection trừu tượng hóa việc duyệt qua Iterator Pattern
public class TransactionBatch implements Iterable<String> {
    private final String[] transactions;
    private int size = 0;

    public TransactionBatch(int capacity) {
        this.transactions = new String[capacity];
    }

    public void add(String txId) {
        if (size < transactions.length) transactions[size++] = txId;
    }

    @Override
    public Iterator<String> iterator() {
        return new Iterator<>() {
            private int cursor = 0;

            @Override
            public boolean hasNext() {
                return cursor < size;
            }

            @Override
            public String next() {
                if (!hasNext()) throw new NoSuchElementException();
                return transactions[cursor++];
            }
        };
    }

    public static void main(String[] args) {
        TransactionBatch batch = new TransactionBatch(5);
        batch.add("TX-001");
        batch.add("TX-002");

        // Duyệt thanh lịch bằng cú pháp for-each nhờ implements Iterable
        for (String tx : batch) {
            System.out.println("Processing transaction: " + tx);
        }
    }
}

package com.bank.concurrent;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

public class FailFastVsFailSafeDemo {
    public static void main(String[] args) {
        // 1. FAIL-FAST: ArrayList
        List<String> fastList = new ArrayList<>(List.of("A", "B", "C"));
        Iterator<String> fastIt = fastList.iterator();
        try {
            while (fastIt.hasNext()) {
                String val = fastIt.next();
                if ("A".equals(val)) {
                    fastList.add("D"); // Thay đổi cấu trúc trực tiếp!
                }
            }
        } catch (java.util.ConcurrentModificationException e) {
            System.out.println("Fail-fast triggered: ConcurrentModificationException!");
        }

        // 2. FAIL-SAFE / SNAPSHOT: CopyOnWriteArrayList
        List<String> safeList = new CopyOnWriteArrayList<>(List.of("A", "B", "C"));
        Iterator<String> safeIt = safeList.iterator();
        while (safeIt.hasNext()) {
            String val = safeIt.next();
            if ("A".equals(val)) {
                safeList.add("D"); // Sửa đổi an toàn, iterator vẫn đọc snapshot cũ
            }
        }
        System.out.println("Fail-safe completed smoothly. Final list size: " + safeList.size()); // 4
    }
}

package com.bank.sorting;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class SortingComparisonArchitecture {

    // 1. Natural Ordering với Comparable: Sắp xếp mặc định theo ID
    record LoanApplication(String id, int creditScore, double amount) implements Comparable<LoanApplication> {
        @Override
        public int compareTo(LoanApplication other) {
            return this.id.compareTo(other.id);
        }
    }

    public static void main(String[] args) {
        List<LoanApplication> applications = new ArrayList<>(List.of(
            new LoanApplication("APP-300", 720, 50000.0),
            new LoanApplication("APP-100", 650, 10000.0),
            new LoanApplication("APP-200", 720, 20000.0)
        ));

        // Sắp xếp tự nhiên theo ID (Comparable)
        applications.sort(null); 
        System.out.println("Sorted naturally by ID: " + applications.get(0).id()); // APP-100

        // 2. Strategy Pattern với Comparator: Sắp xếp ưu tiên Điểm tín dụng GIẢM DẦN, sau đó Số tiền TĂNG DẦN
        Comparator<LoanApplication> riskStrategy = Comparator
            .comparingInt(LoanApplication::creditScore).reversed()
            .thenComparingDouble(LoanApplication::amount);

        applications.sort(riskStrategy);
        System.out.println("Highest score, lowest amount first: " + applications.get(0));
    }
}

