package com.bank.concurrent;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.LongAdder;

public class ConcurrentHashMapArchitectureDemo {
    public static void main(String[] args) {
        // High-Throughput Thread-safe In-Memory Counter Cache
        ConcurrentHashMap<String, LongAdder> metricRegistry = new ConcurrentHashMap<>();

        // Mô phỏng 2 luồng cùng cập nhật metric đồng thời
        Runnable hitCounter = () -> {
            // computeIfAbsent là nguyên tử (Atomic): Đảm bảo chỉ 1 LongAdder được tạo duy nhất
            metricRegistry.computeIfAbsent("PAYMENT_API_HIT", k -> new LongAdder()).increment();
        };

        Thread t1 = new Thread(hitCounter);
        Thread t2 = new Thread(hitCounter);
        t1.start(); t2.start();

        try { t1.join(); t2.join(); } catch (InterruptedException ignored) {}

        System.out.println("Total API Hits safely aggregated: " + 
            metricRegistry.get("PAYMENT_API_HIT").sum());
    }
}

