}

package com.bank.framework;

public abstract class SettlementProcessor {
    protected final String processorCode;

    protected SettlementProcessor(String processorCode) {
        this.processorCode = processorCode;
    }

    // Template Method: Định hình khung xương xử lý chuẩn mực, không cho phép lớp con ghi đè
    public final void executeSettlement(String txId, long amount) {
        validateSecurityToken(txId);
        reserveFunds(txId, amount);
        try {
            dispatchNetworkMessage(txId, amount); // Lớp con cụ thể triển khai
            commitLedger(txId, amount);
        } catch (Exception e) {
            rollbackReservation(txId, amount);
            throw e;
        }
    }

    private void validateSecurityToken(String txId) { System.out.println("Token valid for " + txId); }
    private void reserveFunds(String txId, long amount) { System.out.println("Reserved: " + amount); }
    private void commitLedger(String txId, long amount) { System.out.println("Committed to ledger: " + txId); }
    private void rollbackReservation(String txId, long amount) { System.out.println("Rolled back: " + txId); }

    // Hook method: Lớp con buộc phải định nghĩa kênh mạng cụ thể
    protected abstract void dispatchNetworkMessage(String txId, long amount);
}

