package com.bank.patterns;

public class SingletonShowcase {

    // GIẢI PHÁP 1: Double-Checked Locking với volatile bắt buộc
    public static final class DclSingleton {
        private static volatile DclSingleton instance; // Bắt buộc volatile!

        private DclSingleton() {}

        public static DclSingleton getInstance() {
            if (instance == null) { // Check 1: Tránh synchronize khi đã khởi tạo
                synchronized (DclSingleton.class) {
                    if (instance == null) { // Check 2: Bảo vệ tranh chấp luồng
                        instance = new DclSingleton();
                    }
                }
            }
            return instance;
        }
    }

    // GIẢI PHÁP 2: Bill Pugh Holder (Lazy, Thread-safe, Clean)
    public static final class BillPughSingleton {
        private BillPughSingleton() {}
        private static class Holder {
            private static final BillPughSingleton INSTANCE = new BillPughSingleton();
        }
        public static BillPughSingleton getInstance() { return Holder.INSTANCE; }
    }

    // GIẢI PHÁP 3: Enum Singleton (Miễn nhiễm Reflection & Serialization)
    public enum EnumSingleton {
        INSTANCE;
        public void executeSecurityHandshake() {
            System.out.println("HSM Handshake executed securely.");
        }
    }
}

