package com.bank.sync;

public class ThreadSafeBankAccount {
    private final String accountNumber;
    private long balanceCents;
    private final Object balanceLock = new Object(); // Khóa chuyên biệt (Fine-grained dedicated lock)

    public ThreadSafeBankAccount(String accountNumber, long initialBalance) {
        this.accountNumber = accountNumber;
        this.balanceCents = initialBalance;
    }

    public boolean withdraw(long amountCents) {
        if (amountCents <= 0) throw new IllegalArgumentException("Amount must be positive");

        // Khóa trên đối tượng chuyên biệt thay vì khóa toàn bộ method 'this'
        synchronized (balanceLock) {
            if (balanceCents >= amountCents) {
                // Critical Section: Bảo toàn tính nhất quán nghiệp vụ tuyệt đối
                balanceCents -= amountCents;
                return true;
            }
            return false;
        }
    }

    public long getBalance() {
        synchronized (balanceLock) {
            // Cần synchronize cả hàm đọc để đảm bảo Visibility từ CPU Cache của core khác
            return balanceCents;
        }
    }
}

package com.bank.concurrency;

public class DeadlockPreventionTransferService {

    static class Account {
        final String id;
        long balance;
        Account(String id, long balance) { this.id = id; this.balance = balance; }
    }

    // CHIẾN LƯỢC RESOURCE ORDERING: Luôn khóa theo thứ tự ID bảng chữ cái
    public void transferMoney(Account from, Account to, long amount) {
        Account firstLock = from.id.compareTo(to.id) < 0 ? from : to;
        Account secondLock = from.id.compareTo(to.id) < 0 ? to : from;

        // Khóa theo thứ tự nhất quán 100% -> Triệt tiêu hoàn toàn Circular Wait!
        synchronized (firstLock) {
            synchronized (secondLock) {
                if (from.balance >= amount) {
                    from.balance -= amount;
                    to.balance += amount;
                    System.out.printf("Transferred %d from %s to %s safely.%n", amount, from.id, to.id);
                }
            }
        }
    }

    public static void main(String[] args) {
        Account accA = new Account("ACC-100", 5000);
        Account accB = new Account("ACC-200", 5000);
        DeadlockPreventionTransferService service = new DeadlockPreventionTransferService();

        // Chạy 2 luồng chuyển tiền chéo nhau đồng thời mà không bao giờ bị Deadlock
        new Thread(() -> service.transferMoney(accA, accB, 1000)).start();
        new Thread(() -> service.transferMoney(accB, accA, 500)).start();
    }
}

package com.bank.executors;

import java.util.concurrent.*;

public class EnterpriseExecutorArchitecture {
    public static void main(String[] args) {
        // CẤU HÌNH CHUẨN MỰC SENIOR: Không dùng Executors.newCachedThreadPool bừa bãi
        int corePool = 4;
        int maxPool = 8;
        BlockingQueue<Runnable> taskQueue = new ArrayBlockingQueue<>(100); // Bounded queue!

        ThreadPoolExecutor executor = new ThreadPoolExecutor(
            corePool,
            maxPool,
            60L, TimeUnit.SECONDS,
            taskQueue,
            new ThreadPoolExecutor.CallerRunsPolicy() // Backpressure: Caller tự chạy task nếu queue đầy!
        );

        // Gửi tác vụ
        for (int i = 0; i < 10; i++) {
            final int taskId = i;
            executor.execute(() -> {
                System.out.printf("Task %d executed by %s%n", taskId, Thread.currentThread().getName());
            });
        }

        // Quy trình Graceful Shutdown bắt buộc
        executor.shutdown();
        try {
            if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                executor.shutdownNow(); // Ép dừng nếu quá timeout
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }
}

