package com.bank.racecondition;

import java.util.concurrent.atomic.AtomicInteger;

public class RaceConditionPreventionDemo {

    // GIẢI PHÁP 1: Lock-Free CAS Atomic (Tối ưu cho bài toán đếm tải cao)
    private final AtomicInteger availableVouchers = new AtomicInteger(100);

    public boolean claimVoucherLockFree() {
        // updateAndGet / compareAndSet là nguyên tử tuyệt đối ở cấp độ CPU register
        int remaining = availableVouchers.updateAndGet(current -> current > 0 ? current - 1 : 0);
        return remaining >= 0;
    }

    // GIẢI PHÁP 2: Khóa Pessimistic (Dành cho nghiệp vụ phức tạp nhiều bước)
    private int inventory = 100;
    private final Object inventoryLock = new Object();

    public boolean claimVoucherPessimistic() {
        synchronized (inventoryLock) {
            // Cả bước Check và Act nằm trọn vẹn trong Critical Section
            if (inventory > 0) {
                inventory--;
                return true;
            }
            return false;
        }
    }
}

