        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            // Khởi chạy 50,000 tác vụ I/O đồng thời một cách nhẹ nhàng!
            IntStream.range(0, 50_000).forEach(i -> {
                executor.submit(() -> {
                    try {
                        // Giả lập I/O Blocking: JVM sẽ unmount virtual thread khỏi carrier thread ngay lập tức!
                        Thread.sleep(100);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                });
            });
        } // Khối try-with-resources tự động gọi shutdown() và đợi toàn bộ 50k luồng hoàn thành

        long elapsed = System.currentTimeMillis() - startTime;
        System.out.println("Successfully executed 50,000 Virtual Tasks in: " + elapsed + " ms");
    }
}

