package com.bank.patternmatching;

public class SwitchPatternMatchingMastery {

    record PaymentRequest(String txId, long amountCents, String country) {}
    record FraudAlert(String reason, int severityLevel) {}

    public static String processIncomingEvent(Object event) {
        // Java 21 Modern Switch: Type Pattern + Guarded Pattern (when) + null handling
        return switch (event) {
            case null -> "Invalid Event: Payload is NULL";

            // Guarded Pattern với điều kiện logic 'when'
            case PaymentRequest p when p.amountCents() > 1_000_000_00L -> 
                "Routing to High-Value Escrow Service: " + p.txId();

            case PaymentRequest p when !"VN".equalsIgnoreCase(p.country()) -> 
                "Routing to International Cross-Border Gateway: " + p.txId();

            case PaymentRequest p -> 
                "Standard Domestic Processing: " + p.txId();

            case FraudAlert f when f.severityLevel() >= 9 -> 
                "CRITICAL ALERT: Freezing all accounts immediately! Reason: " + f.reason();

            default -> "Ignored unknown payload type: " + event.getClass().getSimpleName();
        };
    }

    public static void main(String[] args) {
        System.out.println(processIncomingEvent(new PaymentRequest("TX-01", 5_000_000_00L, "VN")));
        System.out.println(processIncomingEvent(new FraudAlert("Unusual IP Geolocation", 10)));
        System.out.println(processIncomingEvent(null)); // Xử lý null an toàn tuyệt đối
    }
}

