package com.bank.threading;

public class WaitVsSleepDemo {
    private static final Object LOCK = new Object();

    public static void demonstrateWait() {
        Thread consumer = new Thread(() -> {
            synchronized (LOCK) {
                try {
                    System.out.println("Consumer acquired lock and calls wait() [RELEASES LOCK]...");
                    LOCK.wait(); // Nhả khóa LOCK và chờ đợi tín hiệu
                    System.out.println("Consumer re-acquired lock and resumed!");
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });

        Thread producer = new Thread(() -> {
            try { Thread.sleep(50); } catch (InterruptedException ignored) {}
            synchronized (LOCK) {
                // Producer có thể vào được block này vì Consumer đã nhả khóa qua wait()!
                System.out.println("Producer acquired lock, sending notify()...");
                LOCK.notify();
            }
        });

        consumer.start();
        producer.start();
    }

    public static void main(String[] args) {
        demonstrateWait();
    }
}

package com.bank.memory;

public class PassByValueProofDemo {

    static class BankAccount {
        String owner;
        BankAccount(String owner) { this.owner = owner; }
    }

    // 1. Cố gắng tráo đổi tham chiếu (Hoàn toàn vô hiệu)
    public static void swap(BankAccount a, BankAccount b) {
        BankAccount temp = a;
        a = b;
        b = temp;
        // Chỉ tráo đổi các biến copy cục bộ trên Stack Frame của hàm swap!
    }

    // 2. Biến đổi trạng thái nội bộ đối tượng (Thành công vì cùng trỏ tới 1 ô nhớ trên Heap)
    public static void changeOwner(BankAccount acc, String newOwner) {
        acc.owner = newOwner; // Mutate đối tượng thực tế trên Heap
    }

    public static void main(String[] args) {
        BankAccount acc1 = new BankAccount("Alice");
        BankAccount acc2 = new BankAccount("Bob");

        swap(acc1, acc2);
        System.out.printf("After swap: acc1=%s, acc2=%s%n", acc1.owner, acc2.owner); // Alice, Bob (Không đổi!)

        changeOwner(acc1, "Alice Wonderland");
        System.out.println("After mutate: acc1=" + acc1.owner); // Alice Wonderland (Đã thay đổi!)
    }
}

