import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

// 2. final class: Ngăn chặn kế thừa phá vỡ tính bất biến
public final class ImmutableUserProfile {

    // 3. private final fields
    private final String userId;
    private final List<String> roles;

    public ImmutableUserProfile(String userId, List<String> roles) {
        this.userId = userId;
        // 4. Defensive Copy tại Constructor: Cách ly hoàn toàn với mảng bên ngoài truyền vào
        if (roles == null) {
            this.roles = Collections.emptyList();
        } else {
            this.roles = List.copyOf(roles); // Java 10+ unmodifiable defensive copy
        }
    }

    // 1. Không có setter, chỉ có getter
    public String getUserId() { return userId; }

    // 4. Trả về Unmodifiable List: Chống việc client gọi getRoles().add("HACKED")
    public List<String> getRoles() {
        return roles; // roles đã là List.copyOf bất biến an toàn
    }

    public static void main(String[] args) {
        List<String> mutableRoles = new ArrayList<>();
        mutableRoles.add("OPERATOR");

        ImmutableUserProfile profile = new ImmutableUserProfile("U-100", mutableRoles);
        mutableRoles.add("ADMIN"); // Cố tình sửa mảng gốc bên ngoài

        System.out.println("Profile roles remain unmutated: " + profile.getRoles()); // Chỉ có OPERATOR
    }
}

package com.bank.cloning;

public class DeepCopyArchitectureDemo {

    static class Address {
        String city;
        Address(String city) { this.city = city; }
        // Copy Constructor cho Address
        Address(Address other) { this.city = other.city; }
    }

    static class CustomerProfile {
        String name;
        Address address;

        CustomerProfile(String name, Address address) {
            this.name = name;
            this.address = address;
        }

        // 1. SHALLOW COPY: Chỉ copy con trỏ address
        public CustomerProfile shallowCopy() {
            return new CustomerProfile(this.name, this.address);
        }

        // 2. DEEP COPY: Khởi tạo mới cả đối tượng Address con độc lập
        public CustomerProfile deepCopy() {
            return new CustomerProfile(this.name, new Address(this.address));
        }
    }

    public static void main(String[] args) {
        CustomerProfile original = new CustomerProfile("Alice", new Address("Hanoi"));

        CustomerProfile shallow = original.shallowCopy();
        CustomerProfile deep = original.deepCopy();

        // Biến đổi trên bản sao Shallow làm hỏng dữ liệu gốc:
        shallow.address.city = "Danang";
        System.out.println("Original city after shallow mutate: " + original.address.city); // Danang (Bị mutate!)

        // Biến đổi trên bản sao Deep hoàn toàn an toàn:
        deep.address.city = "Saigon";
        System.out.println("Original city after deep mutate: " + original.address.city); // Vẫn là Danang (Cách ly an toàn!)
    }
}

package com.bank.jit;

public class JitCompilationWarmupDemo {

    // Phương thức ứng viên hoàn hảo cho JIT Inlining và C2 Optimization
    public static long computeFee(long amount) {
        return amount > 1000 ? (amount * 5) / 100 : 0;
    }

    public static void main(String[] args) {
        System.out.println("=== Demonstrating JVM JIT Tiered Compilation & Warmup ===");

        // Giai đoạn 1: Cold start (Interpreter & Tier 1 C1)
        long startCold = System.nanoTime();
        long sum = 0;
        for (int i = 0; i < 1_000; i++) {
            sum += computeFee(i);
        }
        long durationCold = System.nanoTime() - startCold;

        // Giai đoạn 2: JVM Warm-up (Kích hoạt C2 Compiler Tier 4 qua invocation counters)
        for (int i = 0; i < 200_000; i++) {
            sum += computeFee(i);
        }

        // Giai đoạn 3: Hot execution (Native Code từ Code Cache, zero overhead)
        long startHot = System.nanoTime();
        for (int i = 0; i < 1_000; i++) {
            sum += computeFee(i);
        }
        long durationHot = System.nanoTime() - startHot;

        System.out.printf("Cold Duration: %d ns | Hot JIT Duration: %d ns%n", durationCold, durationHot);
        System.out.println("Speedup ratio: " + (durationCold / Math.max(1, durationHot)) + "x");
    }
}

package com.bank.boxing;

public class AutoboxingPerformancePitfall {
    public static void main(String[] args) {
        // 1. CẠM BẪY HIỆU NĂNG: Khai báo Wrapper trong vòng lặp tính toán
        long startTime = System.currentTimeMillis();
        Long boxedSum = 0L; // Autoboxing liên tục tạo ra hàng triệu instance Long trên Heap!
        for (int i = 0; i < 5_000_000; i++) {
            boxedSum += i; // Tương đương: boxedSum = Long.valueOf(boxedSum.longValue() + i);
        }
        System.out.printf("Boxed Long duration: %d ms, sum: %d%n", 
            (System.currentTimeMillis() - startTime), boxedSum);

        // 2. CHUẨN MỰC TỐI ƯU: Sử dụng Primitive thuần túy trên thanh ghi/stack
        startTime = System.currentTimeMillis();
        long primitiveSum = 0L;
        for (int i = 0; i < 5_000_000; i++) {
            primitiveSum += i;
        }
        System.out.printf("Primitive long duration: %d ms, sum: %d%n", 
            (System.currentTimeMillis() - startTime), primitiveSum);

        // 3. CẠM BẪY UNBOXING NULLPOINTEREXCEPTION:
        Integer nullableCounter = null;
        try {
            int val = nullableCounter; // JVM biên dịch thành nullableCounter.intValue() -> Ném NPE!
        } catch (NullPointerException e) {
            System.out.println("Hidden NPE caught on implicit unboxing of null Wrapper!");
        }
    }
}

package com.bank.bitwise;

public class BitwiseShiftShowcase {
    public static void main(String[] args) {
        int negativeNum = -8;

        // 1. Phép dịch >> (Arithmetic): Bảo toàn dấu âm (chèn bit 1 vào đầu)
        int signedShift = negativeNum >> 1; // -8 / 2 = -4
        System.out.printf("-8 >> 1 = %d (Binary: %s)%n", 
            signedShift, Integer.toBinaryString(signedShift));

        // 2. Phép dịch >>> (Logical): Không dấu (chèn bit 0 vào đầu biến thành số dương khổng lồ)
        int unsignedShift = negativeNum >>> 1;
        System.out.printf("-8 >>> 1 = %d (Binary: %s)%n", 
            unsignedShift, Integer.toBinaryString(unsignedShift));

        // 3. Ứng dụng Binary Search Safe Midpoint kinh điển của JDK:
        int low = 2_000_000_000;
        int high = 2_000_000_000;

        // Cách tính sai: (low + high) = 4,000,000,000 (Tràn thành số âm!)
        int badMid = (low + high) / 2;
        System.out.println("Broken midpoint with division: " + badMid); // -147483648 (Lỗi!)

        // Cách tính chuẩn bằng >>> 1:
        int safeMid = (low + high) >>> 1;
        System.out.println("Safe midpoint with >>> 1: " + safeMid); // 2000000000 (Chính xác 100%!)
    }
}

