package com.bank.security.serialization;

import java.io.*;

public class UserSession implements Serializable {
    @Serial
    private static final long serialVersionUID = 1L;

    private final String userId;

    // TỪ KHÓA TRANSIENT: Tuyệt đối không bao giờ được ghi vào Byte Stream!
    private transient String rawJwtToken;
    private transient long sessionDurationMs;

    public UserSession(String userId, String rawJwtToken) {
        this.userId = userId;
        this.rawJwtToken = rawJwtToken;
        this.sessionDurationMs = System.currentTimeMillis();
    }

    // Tùy biến khôi phục trạng thái sau khi Deserialization
    @Serial
    private void readObject(ObjectInputStream in) throws IOException, ClassNotFoundException {
        in.defaultReadObject(); // Đọc các trường non-transient bình thường (userId)
        // Tái khởi tạo giá trị an toàn cho trường transient thay vì để mặc định null/0
        this.sessionDurationMs = System.currentTimeMillis();
    }

    public static void main(String[] args) throws Exception {
        UserSession session = new UserSession("ADMIN-01", "SECRET_JWT_TOKEN_XYZ");

        // Serialize vào byte array
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ObjectOutputStream oos = new ObjectOutputStream(baos)) {
            oos.writeObject(session);
        }

        // Deserialize lại
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(baos.toByteArray()))) {
            UserSession restored = (UserSession) ois.readObject();
            System.out.println("Restored UserId: " + restored.userId);
            System.out.println("Restored Transient JWT: " + restored.rawJwtToken); // In ra: null (Bảo mật an toàn!)
        }
    }
}

