package com.bank.hashmap;

import java.util.HashMap;
import java.util.Map;

public class TreeificationDemo {

    // Lớp Key cố tình làm hỏng giải thuật băm: Luôn trả về cùng một hashCode
    static final class CollidingKey implements Comparable<CollidingKey> {
        private final int id;
        CollidingKey(int id) { this.id = id; }

        @Override
        public int hashCode() {
            return 42; // Cố tình gây 100% Hash Collision tại cùng 1 bucket!
        }

        @Override
        public boolean equals(Object o) {
            return (o instanceof CollidingKey other) && this.id == other.id;
        }

        // Bắt buộc implements Comparable để Red-Black Tree sắp xếp các node khi hash bằng nhau
        @Override
        public int compareTo(CollidingKey o) {
            return Integer.compare(this.id, o.id);
        }
    }

    public static void main(String[] args) {
        // Khởi tạo HashMap với capacity >= 64 để đủ điều kiện Treeify
        Map<CollidingKey, String> secureMap = new HashMap<>(64);

        // Chèn 10 phần tử cùng rơi vào bucket 42
        for (int i = 0; i < 10; i++) {
            secureMap.put(new CollidingKey(i), "DATA_" + i);
        }

        // Tại phần tử thứ 8 trở đi, bucket tự động chuyển thành Red-Black Tree (TreeNode)!
        // Thao tác get() duy trì O(log N) an toàn tuyệt đối trước DoS attack
        System.out.println("Retrieved from Treeified Bucket: " + secureMap.get(new CollidingKey(9)));
    }
}

package com.bank.hashmap.pitfalls;

import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

public class MutableKeyDisasterDemo {

    static class MutableAccountKey {
        String accountId;
        String status; // Thuộc tính mutable tham gia vào hashCode

        MutableAccountKey(String accountId, String status) {
            this.accountId = accountId;
            this.status = status;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            MutableAccountKey that = (MutableAccountKey) o;
            return Objects.equals(accountId, that.accountId) && Objects.equals(status, that.status);
        }

        @Override
        public int hashCode() {
            return Objects.hash(accountId, status);
        }
    }

    public static void main(String[] args) {
        Map<MutableAccountKey, String> accountMap = new HashMap<>();
        MutableAccountKey key = new MutableAccountKey("ACC-101", "PENDING");

        accountMap.put(key, "Balance: $10,000");
        System.out.println("Initial lookup: " + accountMap.get(key)); // Tìm thấy: Balance: $10,000

        // THẢM HỌA: Biến đổi thuộc tính của key sau khi đã nằm trong Map!
        key.status = "ACTIVE"; // hashCode của key bị thay đổi ngay lập tức!

        // Tra cứu lại bằng chính biến key đó:
        System.out.println("Lookup after mutating key: " + accountMap.get(key)); // In ra: null!
        System.out.println("Map size still remains: " + accountMap.size());     // Size vẫn là 1 (Memory Leak!)
    }
}

package com.bank.cache;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

// Triển khai LRU Cache thanh lịch, chuẩn mực và Thread-safe bằng LinkedHashMap
public class SimpleLruCache<K, V> extends LinkedHashMap<K, V> {
    private final int maxCapacity;

    public SimpleLruCache(int maxCapacity) {
        // initialCapacity, loadFactor, accessOrder = true (BẮT BUỘC để kích hoạt LRU)
        super(maxCapacity + 1, 0.75f, true);
        this.maxCapacity = maxCapacity;
    }

    @Override
    protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
        // Khi số phần tử vượt quá trần, tự động loại bỏ phần tử cũ nhất (Eldest)
        return size() > maxCapacity;
    }

    // Phương thức bọc đồng bộ hóa an toàn đa luồng nếu cần
    public static <K, V> Map<K, V> createThreadSafeLru(int capacity) {
        return Collections.synchronizedMap(new SimpleLruCache<>(capacity));
    }

    public static void main(String[] args) {
        Map<String, String> lru = new SimpleLruCache<>(3);
        lru.put("A", "Alpha");
        lru.put("B", "Beta");
        lru.put("C", "Gamma");

        // Truy cập phần tử A -> A trở thành Most Recently Used (chuyển về cuối)
        lru.get("A");

        // Chèn phần tử D -> Vượt ngưỡng dung lượng 3 -> B (ít dùng nhất) sẽ bị trục xuất!
        lru.put("D", "Delta");

        System.out.println("LRU Cache content: " + lru.keySet()); // [C, A, D] (B đã bị loại bỏ!)
    }
}

package com.bank.streams;

import java.util.*;
import java.util.stream.Collectors;

public class CollectorsToMapPitfallsDemo {

    record UserRole(String username, String role) {}

    public static void main(String[] args) {
        List<UserRole> listWithDuplicates = List.of(
            new UserRole("alice", "OPERATOR"),
            new UserRole("alice", "ADMIN"), // Trùng key 'alice'!
            new UserRole("bob", "AUDITOR")
        );

        // GIẢI PHÁP CHO CẠM BẪY 1: Truyền Merge Function để giải quyết xung đột key
        Map<String, String> safeMap = listWithDuplicates.stream()
            .collect(Collectors.toMap(
                UserRole::username,
                UserRole::role,
                (oldRole, newRole) -> newRole // Khi trùng key: Lấy role mới nhất
            ));
        System.out.println("Resolved Duplicate Key Map: " + safeMap);

        // GIẢI PHÁP CHO CẠM BẪY 2 (Null Values): Không dùng Collectors.toMap
        List<UserRole> listWithNulls = Arrays.asList(
            new UserRole("charlie", null), // Role là null
            new UserRole("david", "MANAGER")
        );

        // Dùng collect với HashMap supplier chấp nhận null value an toàn tuyệt đối
        Map<String, String> nullSafeMap = listWithNulls.stream()
            .collect(HashMap::new, (map, item) -> map.put(item.username(), item.role()), HashMap::putAll);
        System.out.println("Resolved Null Value Map: " + nullSafeMap);
    }
}

package com.bank.streams;

import java.util.List;
import java.util.function.Supplier;
import java.util.stream.Stream;

public class StreamLifecycleAndLazyDemo {
    public static void main(String[] args) {
        List<String> accounts = List.of("ACC-1", "ACC-2", "ACC-3");

        // 1. MINH HỌA LAZY EVALUATION: filter/map sẽ KHÔNG CHẠY nếu thiếu Terminal Operation
        Stream<String> lazyStream = accounts.stream().filter(acc -> {
            System.out.println("Lazy filter evaluated for: " + acc);
            return acc.endsWith("2");
        });
        System.out.println("Pipeline created. Notice: No filter logs printed above!");

        // Kích hoạt Terminal Operation -> Dữ liệu bắt đầu chảy qua pipeline
        List<String> matched = lazyStream.toList();
        System.out.println("Result after terminal op: " + matched);

        // 2. MINH HỌA LỖI TÁI SỬ DỤNG STREAM (Single-use)
        try {
            lazyStream.count(); // Ném IllegalStateException!
        } catch (IllegalStateException e) {
            System.out.println("Cannot reuse stream: " + e.getMessage());
        }

        // 3. GIẢI PHÁP TÁI TẠO STREAM BẰNG SUPPLIER:
        Supplier<Stream<String>> streamSupplier = () -> accounts.stream().filter(s -> s.startsWith("ACC"));
        System.out.println("Count from new stream: " + streamSupplier.get().count());
        System.out.println("List from new stream: " + streamSupplier.get().toList());
    }
}

