package com.bank.strings;

public class StringConcatLoopBenchmark {
    public static void main(String[] args) {
        int count = 30_000;

        // 1. CÁCH LÀM SAI THẢM HỌA: Nối chuỗi bằng + trong vòng lặp (O(N^2) và ngốn RAM)
        long startBad = System.currentTimeMillis();
        String badResult = "";
        for (int i = 0; i < count; i++) {
            badResult += i; // Mỗi bước lặp tạo StringBuilder mới và copy lại toàn bộ chuỗi cũ!
        }
        long durationBad = System.currentTimeMillis() - startBad;

        // 2. CÁCH LÀM CHUẨN SENIOR ARCHITECT: Khởi tạo StringBuilder 1 lần ngoài vòng lặp (O(N))
        long startGood = System.currentTimeMillis();
        StringBuilder sb = new StringBuilder(count * 6); // Pre-size capacity tối ưu
        for (int i = 0; i < count; i++) {
            sb.append(i);
        }
        String goodResult = sb.toString();
        long durationGood = System.currentTimeMillis() - startGood;

        System.out.printf("Concatenation with '+' loop: %d ms%n", durationBad);
        System.out.printf("Optimized StringBuilder loop: %d ms%n", durationGood);
    }
}

