package com.bank.locks;

import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

public class ReentrantLockAdvancedShowcase {
    // Khởi tạo ReentrantLock (mặc định Non-fair lock cho throughput cao nhất)
    private final ReentrantLock lock = new ReentrantLock();
    private final Condition fundsAvailable = lock.newCondition(); // Dedicated Condition
    private long balance = 0;

    public boolean processPaymentWithTimeout(long amount, long timeoutMs) throws InterruptedException {
        // 1. tryLock với Timeout: Ngăn chặn vĩnh viễn nguy cơ treo luồng không giới hạn!
        if (!lock.tryLock(timeoutMs, TimeUnit.MILLISECONDS)) {
            System.out.println("Payment dropped: Lock acquisition timed out!");
            return false; // Fallback an toàn khi hệ thống quá tải
        }

        try {
            // 2. Critical Section được bảo vệ nghiêm ngặt
            balance += amount;
            fundsAvailable.signal(); // Đánh thức các luồng chờ điều kiện này
            return true;
        } finally {
            // BẮT BUỘC: Luôn luôn nhả khóa trong khối finally!
            lock.unlock();
        }
    }
}

package com.bank.sync;

public class InstanceVsClassLockDemo {

    // 1. CLASS LOCK: Khóa trên đối tượng InstanceVsClassLockDemo.class
    // Toàn bộ các luồng ở mọi instance đều bị chặn lẫn nhau!
    public static synchronized void globalClassLockOperation() {
        System.out.println(Thread.currentThread().getName() + " acquired CLASS lock");
        try { Thread.sleep(100); } catch (InterruptedException ignored) {}
    }

    // 2. INSTANCE LOCK: Chỉ khóa trên instance 'this' hiện tại
    // Hai instance khác nhau có thể chạy song song đồng thời!
    public synchronized void instanceLockOperation() {
        System.out.println(Thread.currentThread().getName() + " acquired INSTANCE lock on " + this);
        try { Thread.sleep(100); } catch (InterruptedException ignored) {}
    }

    public static void main(String[] args) {
        InstanceVsClassLockDemo obj1 = new InstanceVsClassLockDemo();
        InstanceVsClassLockDemo obj2 = new InstanceVsClassLockDemo();

        // Hai luồng chạy instanceLock trên 2 object khác nhau -> CHẠY SONG SONG!
        new Thread(obj1::instanceLockOperation, "Worker-1").start();
        new Thread(obj2::instanceLockOperation, "Worker-2").start();

        // Hai luồng chạy globalClassLock -> BẮT BUỘC CHỜ ĐỢI NHAU TUẦN TỰ!
        new Thread(InstanceVsClassLockDemo::globalClassLockOperation, "Worker-3").start();
        new Thread(InstanceVsClassLockDemo::globalClassLockOperation, "Worker-4").start();
    }
}

package com.bank.threads;

public class SafeThreadTerminationArchitecture implements Runnable {
    // Cờ hủy hợp tác bổ trợ
    private volatile boolean keepRunning = true;

    @Override
    public void run() {
        System.out.println("Worker started safely on: " + Thread.currentThread().getName());

        // Định kỳ kiểm tra cờ ngắt hợp tác
        while (keepRunning && !Thread.currentThread().isInterrupted()) {
            try {
                // Thực thi tác vụ xử lý từng batch giao dịch
                processSingleTransaction();
                Thread.sleep(50); // Điểm kiểm tra ngắt tự nhiên
            } catch (InterruptedException e) {
                System.out.println("Worker received interrupt signal during sleep!");
                // KHÔI PHỤC LẠI TRẠNG THÁI NGẮT (Best practice bắt buộc)
                Thread.currentThread().interrupt();
                break; // Thoát vòng lặp để dọn dẹp
            }
        }
        cleanupResources();
    }

    private void processSingleTransaction() { /* Giao dịch an toàn */ }
    private void cleanupResources() { System.out.println("Resources cleaned up cleanly. Thread exiting."); }

    public void cancel() {
        this.keepRunning = false;
    }

    public static void main(String[] args) throws InterruptedException {
        SafeThreadTerminationArchitecture task = new SafeThreadTerminationArchitecture();
        Thread worker = new Thread(task);
        worker.start();

        Thread.sleep(120);
        // Kích hoạt dừng luồng hợp tác chuẩn mực
        worker.interrupt();
        worker.join();
    }
}

package com.bank.executors;

import java.util.concurrent.*;

public class ThreadPoolSizingStrategy {
    public static void main(String[] args) {
        int cpuCores = Runtime.getRuntime().availableProcessors();
        System.out.println("Available CPU Processors: " + cpuCores);

        // 1. TỐI ƯU CHO CPU-BOUND TASKS (Mã hóa, Hash, Tính toán tài chính phức tạp)
        // Số thread = CPU Cores + 1 (1 thread dự phòng bù đắp khi có page fault ngẫu nhiên)
        ThreadPoolExecutor cpuPool = new ThreadPoolExecutor(
            cpuCores,
            cpuCores + 1,
            0L, TimeUnit.MILLISECONDS,
            new ArrayBlockingQueue<>(1000)
        );

        // 2. TỐI ƯU CHO I/O-BOUND TASKS (Truy vấn JDBC, REST API bên ngoài)
        // Giả sử W/C = 4 (Chờ 80ms, Tính 20ms) -> Hệ số nhân là 5
        int ioThreads = cpuCores * (1 + 4);
        ThreadPoolExecutor ioPool = new ThreadPoolExecutor(
            ioThreads,
            ioThreads * 2,
            60L, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(5000)
        );

        System.out.println("Configured CPU Pool Core Size: " + cpuPool.getCorePoolSize());
        System.out.println("Configured I/O Pool Core Size: " + ioPool.getCorePoolSize());

        cpuPool.shutdown();
        ioPool.shutdown();
    }
}

package com.bank.executors;

import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class EnterpriseThreadPoolConfiguration {

    public static ThreadPoolExecutor createResilientPool() {
        int corePool = 8;
        int maxPool = 16;
        long keepAliveSec = 60L;

        // BẮT BUỘC: Sử dụng Bounded Queue (Hàng đợi có giới hạn dung lượng) chống OOM
        BlockingQueue<Runnable> boundedQueue = new ArrayBlockingQueue<>(500);

        // Custom ThreadFactory để đặt tên luồng phục vụ phân tích log và Thread Dump
        ThreadFactory customFactory = new ThreadFactory() {
            private final AtomicInteger threadIndex = new AtomicInteger(1);
            @Override
            public Thread newThread(Runnable r) {
                Thread t = new Thread(r, "PaymentProcessorPool-" + threadIndex.getAndIncrement());
                t.setDaemon(false); // Đảm bảo User Thread hoàn thành nhiệm vụ
                return t;
            }
        };

        // CHÍNH SÁCH BACKPRESSURE: CallerRunsPolicy - Khi đầy, chính luồng gọi submit() sẽ tự chạy task
        RejectedExecutionHandler rejectionHandler = new ThreadPoolExecutor.CallerRunsPolicy();

        return new ThreadPoolExecutor(
            corePool,
            maxPool,
            keepAliveSec,
            TimeUnit.SECONDS,
            boundedQueue,
            customFactory,
            rejectionHandler
        );
    }

    public static void main(String[] args) {
        ThreadPoolExecutor pool = createResilientPool();
        System.out.println("Enterprise thread pool initialized cleanly without OOM traps.");
        pool.shutdown();
    }
}

package com.bank.reactive;

import java.util.concurrent.CompletableFuture;

public class CompletableFutureTransformationsShowcase {

    record User(String id, String email) {}
    record Balance(String userId, long amountCents) {}

    public static void main(String[] args) {
        // 1. thenApply: Map T -> U (Đồng bộ biến đổi giá trị)
        CompletableFuture<String> emailFuture = CompletableFuture.supplyAsync(() -> new User("U1", "alice@bank.com"))
            .thenApply(user -> user.email().toUpperCase()); // Trả về CompletableFuture<String>

        // 2. thenCompose: FlatMap T -> CompletableFuture<U> (Xâu chuỗi tác vụ bất đồng bộ thứ hai)
        CompletableFuture<Balance> balanceFuture = CompletableFuture.supplyAsync(() -> new User("U1", "alice@bank.com"))
            .thenCompose(user -> fetchBalanceAsync(user.id())); // Tránh kiểu CompletableFuture<CompletableFuture<Balance>>

        // 3. thenCombine: Chạy song song 2 luồng độc lập và gộp kết quả
        CompletableFuture<String> consolidatedReport = emailFuture.thenCombine(balanceFuture, (email, balance) -> {
            return "Report for " + email + " | Balance: " + balance.amountCents() + " cents";
        });

        System.out.println("Final result: " + consolidatedReport.join());
    }

    private static CompletableFuture<Balance> fetchBalanceAsync(String userId) {
        return CompletableFuture.supplyAsync(() -> new Balance(userId, 500_000_00L));
    }
}

