        if ("ACC-100".equals(id)) {
            return Optional.of(new Account("ACC-100", 500_000_00L));
        }
        return Optional.empty(); // Không bao giờ trả về null!
    }

    public void processAccount(String id) {
        // 2. TẬN DỤNG CÁC PHƯƠNG THỨC HÀM HIỆN ĐẠI (Java 9+)
        findAccountById(id)
            .map(Account::balanceCents) // Chuyển đổi nếu có giá trị
            .ifPresentOrElse(
                balance -> System.out.println("Account balance: " + balance),
                () -> System.out.println("Account not found in ledger!")
            );

        // 3. orElse vs orElseGet: Luôn dùng orElseGet cho logic cấp phát hoặc tính toán đắt đỏ
        Account fallbackAccount = findAccountById(id)
            .orElseGet(() -> createDefaultEscrowAccount()); // Lazy invocation
    }

    private Account createDefaultEscrowAccount() {
        return new Account("ESCROW-DEFAULT", 0L);
    }
}

package com.bank.generics;

import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;

public class TypeErasureAndTokenShowcase {

    // Kỹ thuật Super Type Token (Neal Gafter): Giữ lại Generic Type qua Subclassing Metadata
    public abstract static class TypeReference<T> {
        private final Type type;

        protected TypeReference() {
            Type superClass = getClass().getGenericSuperclass();
            if (superClass instanceof ParameterizedType parameterized) {
                // Đọc thông tin Generic Type được lưu trong Class Signature Bytecode!
                this.type = parameterized.getActualTypeArguments()[0];
            } else {
                throw new IllegalArgumentException("TypeReference must be parameterized");
            }
        }

        public Type getType() { return type; }
    }

    public static void main(String[] args) {
        // 1. Minh họa Type Erasure: Cả 2 List đều có class là java.util.ArrayList tại runtime
        java.util.List<String> stringList = new java.util.ArrayList<>();
        java.util.List<Integer> intList = new java.util.ArrayList<>();
        System.out.println("Classes are identical at runtime: " + (stringList.getClass() == intList.getClass())); // true

        // 2. Khắc phục Type Erasure bằng Super Type Token (Chuẩn mực Jackson / Gson):
        TypeReference<java.util.List<String>> token = new TypeReference<>() {};
        System.out.println("Recovered generic runtime type: " + token.getType()); // java.util.List<java.lang.String>
    }
}
